export type IconName = keyof typeof PATHS;

export default function Icon({ name, fill = false, className = 'w-5 h-5' }: { name: IconName; fill?: boolean; className?: string }) {
  const id = `ig${useId().replace(/[^\w-]/g, '')}`;
  if (fill) {
    return <svg viewBox="0 0 256 256" fill="currentColor" aria-hidden="true" className={`shrink-0 ${className}`}
      dangerouslySetInnerHTML={{ __html: PATHS[name].fill }} />;
  }
  // 위는 살짝 옅고 아래로 갈수록 진하게 (시안의 은은한 광택). 연한 채움(opacity 0.2)도 같은 그라데이션을 탄다
  return (
    <svg viewBox="0 0 256 256" fill={`url(#${id})`} aria-hidden="true" className={`shrink-0 ${className}`}>
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="0.35" y2="1">
          <stop offset="0" stopColor="currentColor" stopOpacity={0.78} />
          <stop offset="1" stopColor="currentColor" />
        </linearGradient>
      </defs>
      <g dangerouslySetInnerHTML={{ __html: PATHS[name].regular }} />
    </svg>
  );
}

// 연한 동그라미 안의 아이콘 (tone 으로 색 지정)
const TONES = {
  gold: 'bg-amber-50 text-amber-700',
  rose: 'bg-rose-50 text-rose-600',
  sky: 'bg-sky-50 text-sky-800',
  violet: 'bg-violet-50 text-violet-700',
  stone: 'bg-stone-100 text-stone-700',
  red: 'bg-red-50 text-red-600',
  green: 'bg-emerald-50 text-emerald-700',
} as const;
export type IconTone = keyof typeof TONES;

export function IconBadge({ name, tone = 'stone', fill = false, size = 'md' }: { name: IconName; tone?: IconTone; fill?: boolean; size?: 'sm' | 'md' | 'lg' }) {
  const box = size === 'lg' ? 'w-10 h-10' : size === 'md' ? 'w-8 h-8' : 'w-6 h-6';
  const ico = size === 'lg' ? 'w-[1.375rem] h-[1.375rem]' : size === 'md' ? 'w-[1.125rem] h-[1.125rem]' : 'w-3.5 h-3.5';
  return (
    <span className={`inline-flex items-center justify-center rounded-full shrink-0 ${box} ${TONES[tone]}`}>
      <Icon name={name} fill={fill} className={ico} />
    </span>
  );
}
